const page = await browser.goto('https://en.wikipedia.org/wiki/World_War_II');
const info = await browser.js(`
(function(){
  const refList = document.querySelectorAll('ol.references > li');
  const total = refList.length;
  const item275 = refList[274];
  const link = item275.querySelector('a[href^="#CITEREF"]');
  const href = link ? link.getAttribute('href') : null;
  const targetId = href ? href.slice(1) : null;
  const target = targetId ? document.getElementById(targetId) : null;
  return {
    total,
    item275_id: item275.id,
    item275_text: item275.textContent.trim(),
    href,
    targetId,
    target_found: !!target,
    target_text: target ? target.textContent.trim() : null,
    target_outerHTML: target ? target.outerHTML : null
  };
})()
`);
return { url: page.url, info };

// Click the back-link within the reference list item to navigate, or directly click the reference link in the ref list
