const page = await browser.goto('https://en.wikipedia.org/wiki/World_War_II');
// Find the reference item 275, get its number as rendered, and scroll to it
const info = await browser.js(`
(function(){
  const refList = document.querySelectorAll('ol.references > li');
  const item275 = refList[274];
  // get rendered number via ::marker is not readable via JS directly, but ol start + index gives number.
  // Add a temporary bright outline to item 275 for visual proof
  item275.style.outline = '5px solid red';
  item275.style.backgroundColor = '#fff59d';
  item275.scrollIntoView({block:'center'});
  return {
    id: item275.id,
    text: item275.textContent.trim(),
    listStart: document.querySelector('ol.references').start || 1
  };
})()
`);
return info;

// Reset previous styling first
await browser.js(`
(function(){
  const el = document.getElementById('cite_note-Chubarov_2001_122-274');
  if(el){ el.style.outline=''; el.style.backgroundColor=''; }
})()
`);
// Now let's check: are there any nested/hidden li's, or is start!=1, or are there li's with different numbering (like a,b sub-notes)?
// The screenshot shows "274. ^ a b Zeiler 2004" - meaning item 274 has multiple backlinks (a b) but is still ONE list item.
// So indices should match... unless some earlier list items were skipped in rendering due to CSS counter reset or list-style.
// Let's check computed style and also check if there are multiple <ol class="references"> or nested ones causing miscount.
const check = await browser.js(`
(function(){
  const lists = document.querySelectorAll('ol.references');
  return {
    numLists: lists.length,
    lengths: Array.from(lists).map(l=>l.children.length)
  };
})()
`);
return check;
